#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Dynamic Load Balancing for A2A Mesh task delegation.
Automatic node selection based on CPU/memory scoring instead of round-robin.

This module provides:
  - NodeMetrics: dataclass holding CPU/memory/load info for a node
  - MetricsCollector: gathers live system metrics (psutil-based with fallback)
  - LoadBalancer: scores and selects nodes dynamically
  - A2AMeshNode: minimal mesh node that uses the load balancer for delegation
  - CLI demo / integration test runnable from repo root
"""

from __future__ import annotations

import dataclasses
import hashlib
import json
import logging
import os
import socket
import threading
import time
import uuid
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Tuple

# ---------------------------------------------------------------------------
# Optional psutil import with graceful fallback to /proc-based readings
# ---------------------------------------------------------------------------
try:
    import psutil

    _HAS_PSUTIL = True
except ImportError:  # pragma: no cover
    _HAS_PSUTIL = False

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("a2a_mesh.lb")


# ---------------------------------------------------------------------------
# Metrics
# ---------------------------------------------------------------------------
@dataclass
class NodeMetrics:
    """Snapshot of a node's resource availability."""

    node_id: str
    cpu_percent: float  # 0-100, higher = busier
    mem_percent: float  # 0-100, higher = busier
    cpu_count: int
    mem_total_mb: float
    mem_available_mb: float
    active_tasks: int = 0
    last_updated: float = field(default_factory=time.time)

    # Scoring weights — tunable
    W_CPU: float = 0.45
    W_MEM: float = 0.35
    W_TASKS: float = 0.20

    def score(self) -> float:
        """
        Return a score in [0, 1] where higher = better candidate.
        Combines inverse CPU usage, inverse memory usage, and inverse task count.
        """
        cpu_avail = max(0.0, 1.0 - (self.cpu_percent / 100.0))
        mem_avail = max(0.0, self.mem_available_mb / self.mem_total_mb) if self.mem_total_mb > 0 else 0.0
        # Normalize active tasks: assume 0-20 tasks is the interesting range
        task_avail = max(0.0, 1.0 - (self.active_tasks / 20.0))
        return self.W_CPU * cpu_avail + self.W_MEM * mem_avail + self.W_TASKS * task_avail

    def to_dict(self) -> Dict[str, Any]:
        return {
            "node_id": self.node_id,
            "cpu_percent": round(self.cpu_percent, 2),
            "mem_percent": round(self.mem_percent, 2),
            "cpu_count": self.cpu_count,
            "mem_total_mb": round(self.mem_total_mb, 2),
            "mem_available_mb": round(self.mem_available_mb, 2),
            "active_tasks": self.active_tasks,
            "score": round(self.score(), 4),
            "last_updated": self.last_updated,
        }


# ---------------------------------------------------------------------------
# Metrics collection
# ---------------------------------------------------------------------------
class MetricsCollector:
    """Collects local system metrics, with psutil or /proc fallback."""

    def __init__(self, node_id: str):
        self.node_id = node_id

    def collect(self, active_tasks: int = 0) -> NodeMetrics:
        if _HAS_PSUTIL:
            cpu_percent = psutil.cpu_percent(interval=0.1)
            vm = psutil.virtual_memory()
            return NodeMetrics(
                node_id=self.node_id,
                cpu_percent=cpu_percent,
                mem_percent=vm.percent,
                cpu_count=psutil.cpu_count() or 1,
                mem_total_mb=vm.total / (1024 * 1024),
                mem_available_mb=vm.available / (1024 * 1024),
                active_tasks=active_tasks,
            )
        return self._collect_fallback(active_tasks)

    def _collect_fallback(self, active_tasks: int) -> NodeMetrics:
        """Linux /proc-based fallback when psutil is unavailable."""
        cpu_count = os.cpu_count() or 1

        # CPU usage via /proc/stat (two quick samples)
        def _read_cpu():
            try:
                with open("/proc/stat", "r") as f:
                    line = f.readline()
                    parts = line.split()[1:]
                    return sum(int(x) for x in parts)
            except Exception:
                return 0

        t1 = _read_cpu()
        time.sleep(0.1)
        t2 = _read_cpu()
        cpu_percent = min(100.0, max(0.0, ((t2 - t1) / (0.1 * cpu_count * 100)) * 100)) if t2 > t1 else 0.0

        # Memory via /proc/meminfo
        mem_total_mb = 0.0
        mem_avail_mb = 0.0
        mem_percent = 0.0
        try:
            with open("/proc/meminfo", "r") as f:
                for line in f:
                    if line.startswith("MemTotal:"):
                        mem_total_mb = int(line.split()[1]) / 1024
                    elif line.startswith("MemAvailable:"):
                        mem_avail_mb = int(line.split()[1]) / 1024
            if mem_total_mb > 0:
                mem_percent = ((mem_total_mb - mem_avail_mb) / mem_total_mb) * 100
        except Exception:
            mem_total_mb = 4096.0
            mem_avail_mb = 2048.0
            mem_percent = 50.0

        return NodeMetrics(
            node_id=self.node_id,
            cpu_percent=cpu_percent,
            mem_percent=mem_percent,
            cpu_count=cpu_count,
            mem_total_mb=mem_total_mb,
            mem_available_mb=mem_avail_mb,
            active_tasks=active_tasks,
        )


# ---------------------------------------------------------------------------
# Load Balancer
# ---------------------------------------------------------------------------
class LoadBalancer:
    """
    Dynamic load balancer that selects the best node based on CPU/memory scoring.

    Replaces round-robin with a weighted scoring approach. Nodes report their
    metrics periodically; the balancer picks the highest-scoring node, with
    small random jitter to avoid thundering-herd on ties.
    """

    METRICS_TTL: float = 10.0  # seconds before metrics are considered stale

    def __init__(self, self_node_id: str):
        self.self_node_id = self_node_id
        self._peers: Dict[str, NodeMetrics] = {}
        self._lock = threading.Lock()
        self._round_robin_idx: int = 0  # fallback only

    # -- registration / updates ------------------------------------------------

    def register_peer(self, node_id: str) -> None:
        with self._lock:
            if node_id not in self._peers and node_id != self.self_node_id:
                self._peers[node_id] = NodeMetrics(
                    node_id=node_id,
                    cpu_percent=50.0,
                    mem_percent=50.0,
                    cpu_count=1,
                    mem_total_mb=4096.0,
                    mem_available_mb=2048.0,
                    active_tasks=0,
                )
                logger.debug("Registered peer node: %s", node_id)

    def unregister_peer(self, node_id: str) -> None:
        with self._lock:
            self._peers.pop(node_id, None)

    def update_peer_metrics(self, metrics: NodeMetrics) -> None:
        with self._lock:
            self._peers[metrics.node_id] = metrics

    def update_self_metrics(self, metrics: NodeMetrics) -> None:
        with self._lock:
            self._peers[metrics.node_id] = metrics

    def get_all_metrics(self) -> List[NodeMetrics]:
        with self._lock:
            return list(self._peers.values())

    # -- selection -------------------------------------------------------------

    def select_node(
        self,
        exclude: Optional[set] = None,
        min_score: float = 0.0,
        task_weight: Optional[Dict[str, float]] = None,
    ) -> Optional[str]:
        """
        Select the best node for delegation.

        Args:
            exclude: set of node_ids to exclude (e.g. already-tried nodes)
            min_score: minimum score threshold; if no node meets it, returns None
            task_weight: optional per-node weight adjustments (e.g. skill affinity)

        Returns:
            node_id of the selected node, or None if no suitable node found.
        """
        exclude = exclude or set()
        with self._lock:
            now = time.time()
            candidates: List[Tuple[str, float]] = []

            for nid, m in self._peers.items():
                if nid in exclude:
                    continue
                # Expire stale metrics
                if now - m.last_updated > self.METRICS_TTL:
                    logger.warning("Metrics for %s are stale (%.1fs), skipping", nid, now - m.last_updated)
                    continue

                s = m.score()
                if task_weight and nid in task_weight:
                    s *= task_weight[nid]
                if s >= min_score:
                    candidates.append((nid, s))

            if not candidates:
                # Fallback: round-robin among all known peers (excluding stale check)
                all_peers = [nid for nid in self._peers if nid not in exclude]
                if all_peers:
                    self._round_robin_idx = (self._round_robin_idx + 1) % len(all_peers)
                    chosen = all_peers[self._round_robin_idx]
                    logger.info("No scored candidates; round-robin fallback -> %s", chosen)
                    return chosen
                return None

            # Sort by score descending; on near-ties, add deterministic jitter
            candidates.sort(key=lambda x: x[1], reverse=True)
            best_score = candidates[0][1]
            top = [c for c in candidates if c[1] >= best_score * 0.98]

            if len(top) == 1:
                return top[0][0]

            # Deterministic tie-break via hash of (task_id-like, node_id)
            tiebreak_seed = str(time.time_ns())
            top.sort(
                key=lambda x: int(hashlib.md5(f"{tiebreak_seed}:{x[0]}".encode()).hexdigest(), 16)
            )
            return top[0][0]

    def select_with_retry(
        self,
        max_attempts: int = 3,
        task_weight: Optional[Dict[str, float]] = None,
    ) -> Optional[str]:
        """Try to select a node, retrying with exclusions on failure."""
        tried: set = set()
        for attempt in range(max_attempts):
            node = self.select_node(exclude=tried, task_weight=task_weight)
            if node:
                return node
            if not tried:
                break
        return None


# ---------------------------------------------------------------------------
# Minimal A2A Mesh Node (demonstration / integration)
# ---------------------------------------------------------------------------
class A2AMeshNode:
    """
    A minimal mesh node that uses dynamic load balancing for task delegation.

    In a real deployment, peer metrics would be exchanged via heartbeat messages.
    Here we simulate multiple nodes for demonstration.
    """

    def __init__(self, node_id: Optional[str] = None, host: str = "0.0.0.0", port: int = 0):
        self.node_id = node_id or f"node_{socket.gethostname()}_{uuid.uuid4().hex[:8]}"
        self.host = host
        self.port = port
        self.collector = MetricsCollector(self.node_id)
        self.balancer = LoadBalancer(self.node_id)
        self.active_tasks: int = 0
        self._task_results: Dict[str, Any] = {}
        self._stop = threading.Event()

        # Register self
        self._refresh_self_metrics()

    def _refresh_self_metrics(self) -> NodeMetrics:
        m = self.collector.collect(active_tasks=self.active_tasks)
        self.balancer.update_self_metrics(m)
        return m

    def start_metrics_loop(self, interval: float = 5.0) -> None:
        """Background thread that periodically refreshes local metrics."""

        def _loop():
            while not self._stop.is_set():
                try:
                    self._refresh_self_metrics()
                except Exception as e:
                    logger.error("Metrics refresh error: %s", e)
                self._stop.wait(interval)

        t = threading.Thread(target=_loop, daemon=True, name=f"metrics-{self.node_id}")
        t.start()

    def stop(self) -> None:
        self._stop.set()

    # -- peer simulation -------------------------------------------------------

    def add_simulated_peer(self, node_id: str, metrics: NodeMetrics) -> None:
        """Add a peer with given metrics (simulated for demo)."""
        self.balancer.register_peer(node_id)
        self.balancer.update_peer_metrics(metrics)

    def update_simulated_peer(self, node_id: str, **kwargs) -> None:
        """Update a simulated peer's metrics."""
        with self.balancer._lock:
            if node_id in self.balancer._peers:
                m = self.balancer._peers[node_id]
                for k, v in kwargs.items():
                    if hasattr(m, k):
                        setattr(m, k, v)
                m.last_updated = time.time()

    # -- task delegation -------------------------------------------------------

    def delegate_task(self, task: Dict[str, Any]) -> Dict[str, Any]:
        """
        Delegate a task to the best-scoring node.

        Returns a delegation record with the selected node and task info.
        """
        self.active_tasks += 1
        try:
            self._refresh_self_metrics()

            # Optional: skill-based weight adjustment
            task_weight: Dict[str, float] = {}
            required_skills = task.get("skills", [])
            if required_skills:
                # In real impl, peers would advertise skills; here we use a simple hash
                for nid in list(self.balancer._peers.keys()):
                    skill_match = sum(
                        1 for s in required_skills if int(hashlib.md5(f"{nid}:{s}".encode()).hexdigest(), 16) % 3 == 0
                    )
                    task_weight[nid] = 1.0 + (0.1 * skill_match)

            selected = self.balancer.select_with_retry(max_attempts=3, task_weight=task_weight)
            if not selected:
                return {
                    "status": "no_node",
                    "task_id": task.get("id"),
                    "error": "No suitable node available for delegation",
                }

            record = {
                "task_id": task.get("id", uuid.uuid4().hex),
                "delegated_to": selected,
                "delegated_by": self.node_id,
                "timestamp": time.time(),
                "task": task,
                "status": "delegated",
            }
            logger.info("Task %s delegated to %s (score-based)", record["task_id"], selected)
            return record
        finally:
            self.active_tasks = max(0, self.active_tasks - 1)

    def get_status(self) -> Dict[str, Any]:
        m = self._refresh_self_metrics()
        return {
            "node_id": self.node_id,
            "self_metrics": m.to_dict(),
            "peers": {nid: m.to_dict() for nid, m in self.balancer._peers.items() if nid != self.node_id},
            "active_tasks": self.active_tasks,
        }


# ---------------------------------------------------------------------------
# Demo / Integration test
# ---------------------------------------------------------------------------
def _demo():
    """Simulate a mesh with several nodes and demonstrate dynamic selection."""
    print("=" * 72)
    print("A2A Mesh — Dynamic Load Balancing Demo (CPU/Memory scoring)")
    print("=" * 72)

    # Create the local node
    local = A2AMeshNode(node_id="node_local")
    local.start_metrics_loop(interval=2.0)

    # Simulate peer nodes with varying load
    peers = [
        NodeMetrics("node_alpha", cpu_percent=15.0, mem_percent=30.0, cpu_count=8, mem_total_mb=16384, mem_available_mb=11000, active_tasks=1),
        NodeMetrics("node_beta", cpu_percent=85.0, mem_percent=80.0, cpu_count=4, mem_total_mb=8192, mem_available_mb=1600, active_tasks=8),
        NodeMetrics("node_gamma", cpu_percent=40.0, mem_percent=50.0, cpu_count=16, mem_total_mb=32768, mem_available_mb=16000, active_tasks=3),
        NodeMetrics("node_delta", cpu_percent=60.0, mem_percent=45.0, cpu_count=8, mem_total_mb=16384, mem_available_mb=9000, active_tasks=5),
    ]
    for p in peers:
        local.add_simulated_peer(p.node_id, p)

    print("\n--- Node Scores ---")
    all_metrics = local.balancer.get_all_metrics()
    all_metrics.sort(key=lambda m: m.score(), reverse=True)
    for m in all_metrics:
        print(f"  {m.node_id:20s}  CPU={m.cpu_percent:5.1f}%  MEM={m.mem_percent:5.1f}%  "
              f"tasks={m.active_tasks:2d}  score={m.score():.4f}")

    print("\n--- Task Delegation (10 tasks) ---")
    task_ids = [f"task_{i:03d}" for i in range(10)]
    delegation_log: List[Dict[str, Any]] = []

    for i, tid in enumerate(task_ids):
        # Simulate load changes over time
        if i == 3:
            print("\n  [sim] node_alpha CPU spikes to 90%")
            local.update_simulated_peer("node_alpha", cpu_percent=90.0, mem_percent=85.0, active_tasks=7)
        if i == 6:
            print("\n  [sim] node_beta frees up (CPU drops to 10%)")
            local.update_simulated_peer("node_beta", cpu_percent=10.0, mem_percent=20.0, active_tasks=0)

        task = {
            "id": tid,
            "type": "computation",
            "payload": f"compute something #{i}",
            "skills": ["math", "io"] if i % 2 == 0 else ["io"],
        }
        result = local.delegate_task(task)
        delegation_log.append(result)
        status = result.get("status", "unknown")
        target = result.get("delegated_to", "N/A")
        print(f"  {tid}  ->  {target:20s}  [{status}]")

    print("\n--- Delegation Distribution ---")
    from collections import Counter
    targets = [r.get("delegated_to") for r in delegation_log if r.get("delegated_to")]
    for node, count in sorted(Counter(targets).items()):
        bar = "█" * count
        print(f"  {node:20s}  {count:2d}  {bar}")

    print("\n--- Final Node Status ---")
    status = local.get_status()
    print(json.dumps(status, indent=2, default=str))

    local.stop()
    print("\nDone. Dynamic load balancing is working — delegation follows capacity, not round-robin.")


def _benchmark():
    """Quick benchmark: scoring vs round-robin fairness under uniform load."""
    print("\n--- Benchmark: 1000 selections, 5 nodes, uniform load ---")
    lb = LoadBalancer("bench_self")
    for i in range(5):
        lb.update_peer_metrics(NodeMetrics(
            f"bench_node_{i}",
            cpu_percent=50.0, mem_percent=50.0, cpu_count=4,
            mem_total_mb=8192, mem_available_mb=4096, active_tasks=2,
        ))
    from collections import Counter
    picks = Counter()
    for _ in range(1000):
        n = lb.select_node()
        if n:
            picks[n] += 1
    for node, count in sorted(picks.items()):
        print(f"  {node}: {count}")
    # With uniform metrics, distribution should be roughly even (deterministic tie-break)
    vals = list(picks.values())
    if vals:
        spread = max(vals) - min(vals)
        print(f"  Spread (max-min): {spread}  (low = fair tie-breaking)")


if __name__ == "__main__":
    _demo()
    _benchmark()